# --- In-memory store ---
_tasks: dict[int, dict] = {}
_next_id: int = 1

VALID_STATUSES = {"pendiente", "en progreso", "completada"}


def _create_task(data: dict) -> tuple[dict, int]:
    global _next_id
    errors = []
    if "titulo" not in data or not isinstance(data.get("titulo"), str) or not data["titulo"].strip():
        errors.append("El campo 'titulo' es obligatorio y debe ser un string no vacío.")
    if "descripcion" not in data or not isinstance(data.get("descripcion"), str):
        errors.append("El campo 'descripcion' es obligatorio y debe ser un string.")
    estado = data.get("estado", "pendiente")
    if estado not in VALID_STATUSES:
        errors.append(f"El campo 'estado' debe ser uno de: {', '.join(sorted(VALID_STATUSES))}")
    if errors:
        return {"error": "Validación fallida", "detalles": errors}, 400

    task = {
        "id": _next_id,
        "titulo": data["titulo"].strip(),
        "descripcion": data["descripcion"],
        "estado": estado,
    }
    _tasks[_next_id] = task
    _next_id += 1
    return task, 201


def _get_all_tasks() -> tuple[list, int]:
